// Service worker for the standalone build (generated by tools/post_build_pwa.py).
// Pages (navigations) and release.json: NETWORK-FIRST, so a new build shows on the next load (cache only when offline).
// Other same-origin assets: cache-first (the cache name changes with every build). Old caches are deleted on activate.
const CACHE = 'cnta-c87a6c996d';
const SHELL = ['./', './index.html', './manifest.webmanifest', './icon.svg'];
self.addEventListener('install', e => {
  e.waitUntil(caches.open(CACHE).then(c => c.addAll(SHELL)).then(() => self.skipWaiting()));
});
self.addEventListener('activate', e => {
  e.waitUntil(caches.keys().then(keys => Promise.all(keys.filter(k => k.startsWith('cnta-') && k !== CACHE).map(k => caches.delete(k)))).then(() => self.clients.claim()));
});
const keep = (req, res) => { if (res && res.ok && res.type === 'basic') { const copy = res.clone(); caches.open(CACHE).then(c => c.put(req, copy)); } return res; };
self.addEventListener('fetch', e => {
  const req = e.request;
  if (req.method !== 'GET') return;
  const url = new URL(req.url);
  if (url.origin !== self.location.origin) return;          // fonts and other hosts: browser default
  const fresh = req.mode === 'navigate' || /\/(index\.html|release\.json)$/.test(url.pathname) || url.pathname.endsWith('/');
  if (fresh) {
    e.respondWith(fetch(req, {cache: 'no-store'}).then(res => keep(req, res))
      .catch(() => caches.match(req, {ignoreSearch: true}).then(hit => hit || caches.match('./index.html'))));
    return;
  }
  e.respondWith(
    caches.match(req, {ignoreSearch: true}).then(hit => hit || fetch(req).then(res => keep(req, res))
      .catch(() => Response.error()))
  );
});
